/*
 * NoiseLessBurp asset guard: paste ABOVE all code generated by
 * HTTP history > Settings mode > Convert to script.
 * Existing converted filters remain intact BELOW this block.
 * For a fully switchable in-scope filter, load NoiseLessBurp.bambda instead:
 * setting this guard's SHOW_ONLY_IN_SCOPE=false cannot override any scope
 * restriction already present in Burp's generated code.
 */
{
    // ===== SWITCHES =====
    boolean SHOW_ONLY_IN_SCOPE = true;
    boolean HIDE_JAVASCRIPT = true;
    boolean HIDE_CSS = true;
    boolean HIDE_EXTENSIONLESS_BUNDLES = true;
    boolean PRESERVE_ERROR_RESPONSES = true;
    boolean PRESERVE_DYNAMIC_MIME = true;
    boolean PRESERVE_SOURCE_MAPS = true;
    boolean PRESERVE_ANNOTATED_ITEMS = true;
    // ====================

    var req = requestResponse.request();
    if (SHOW_ONLY_IN_SCOPE && !req.isInScope()) return false;
    boolean responseAvailable = requestResponse.hasResponse();
    int code = responseAvailable ? requestResponse.response().statusCode() : 0;
    if (!(PRESERVE_ERROR_RESPONSES && responseAvailable && code >= 400) &&
        !(PRESERVE_ANNOTATED_ITEMS &&
          (requestResponse.annotations().hasNotes() ||
           requestResponse.annotations().hasHighlightColor())) &&
        ("GET".equalsIgnoreCase(req.method()) || "HEAD".equalsIgnoreCase(req.method())) &&
        responseAvailable) {
        var mime = requestResponse.mimeType();
        String path = req.pathWithoutQuery().toLowerCase(java.util.Locale.ROOT);
        boolean dynamic = (PRESERVE_SOURCE_MAPS && path.endsWith(".map")) ||
            (PRESERVE_DYNAMIC_MIME &&
             (mime == MimeType.HTML || mime == MimeType.JSON || mime == MimeType.XML ||
              mime == MimeType.YAML || mime == MimeType.SSE));
        if (!dynamic) {
            String leaf = path.substring(path.lastIndexOf('/') + 1);
            boolean jsBundle = HIDE_EXTENSIONLESS_BUNDLES &&
                (leaf.equals("js") || (leaf.length() > 2 && leaf.endsWith("js")) ||
                 path.contains("/js/") || path.contains("/scripts/"));
            boolean cssBundle = HIDE_EXTENSIONLESS_BUNDLES &&
                (leaf.equals("css") || (leaf.length() > 3 && leaf.endsWith("css")) ||
                 path.contains("/css/") || path.contains("/styles/") ||
                 path.contains("/stylesheets/"));
            if (HIDE_JAVASCRIPT && (path.endsWith(".js") || path.endsWith(".mjs") ||
                    path.endsWith(".cjs") || jsBundle || mime == MimeType.SCRIPT)) return false;
            if (HIDE_CSS && (path.endsWith(".css") || cssBundle || mime == MimeType.CSS)) return false;
        }
    }
}
